previewCss:
.darma-loader-darma-b16-sheet-music-scroll { --accent: var(--loader-color, #4338ca); --accent-2: var(--loader-secondary-color, #f472b6); width: var(--loader-size, 132px); height: calc(var(--loader-size, 132px) * .48); position: relative; overflow: hidden; border-radius: 6px; }
.darma-loader-darma-b16-sheet-music-scroll .darma-loader-darma-b16-sheet-music-scroll__staff { position: absolute; left: 0; right: 0; top: 18%; height: 64%; background: repeating-linear-gradient(color-mix(in srgb, var(--accent) 50%, transparent) 0 2px, transparent 2px 25%); }
.darma-loader-darma-b16-sheet-music-scroll i { position: absolute; width: 11%; height: 15%; border-radius: 50%; background: var(--accent-2); transform: rotate(-18deg); animation: darma-loader-darma-b16-sheet-music-scroll-score-scroll calc(var(--loader-speed, 1s) * 3.2) linear infinite; }
.darma-loader-darma-b16-sheet-music-scroll i::after { content: ''; position: absolute; left: 84%; bottom: 30%; width: 12%; height: 200%; border-radius: 2px; background: var(--accent-2); }
.darma-loader-darma-b16-sheet-music-scroll i:nth-of-type(1) { top: 22%; }
.darma-loader-darma-b16-sheet-music-scroll i:nth-of-type(2) { top: 54%; animation-delay: calc(var(--loader-speed, 1s) * -.64); }
.darma-loader-darma-b16-sheet-music-scroll i:nth-of-type(3) { top: 38%; animation-delay: calc(var(--loader-speed, 1s) * -1.28); }
.darma-loader-darma-b16-sheet-music-scroll i:nth-of-type(4) { top: 66%; animation-delay: calc(var(--loader-speed, 1s) * -1.92); }
.darma-loader-darma-b16-sheet-music-scroll i:nth-of-type(5) { top: 30%; animation-delay: calc(var(--loader-speed, 1s) * -2.56); }
.darma-loader-darma-b16-sheet-music-scroll .darma-loader-darma-b16-sheet-music-scroll__playhead { position: absolute; left: 26%; top: 6%; bottom: 6%; width: 3%; border-radius: 2px; background: var(--accent); box-shadow: 0 0 10px color-mix(in srgb, var(--accent) 70%, transparent); animation: darma-loader-darma-b16-sheet-music-scroll-score-beat calc(var(--loader-speed, 1s) * .64) ease-in-out infinite; }
@keyframes darma-loader-darma-b16-sheet-music-scroll-score-scroll { from { left: 104%; } to { left: -14%; } }
@keyframes darma-loader-darma-b16-sheet-music-scroll-score-beat { 0%, 100% { opacity: .55; transform: scaleY(.9); } 50% { opacity: 1; transform: scaleY(1); } }

